import 'package:ecommerce/view/approute.dart';import 'package:flutter/material.dart';import 'package:get/get.dart';import '../../core/classes/crud.dart';import '../../core/classes/statusrequest.dart';import '../../core/counstant/colore.dart';import '../../core/servises/Mysevice.dart';import '../../data/datasource/car/cart.dart';import '../../data/model/cartmodel.dart';import '../../data/model/getitems_model/getitems.dart';import '../../data/model/itemscolormodel.dart';abstract class ProductDetailsController extends GetxController {  viewcoloritem(String item);}class ProductDetailsControllerImp extends ProductDetailsController {  late itemsmodelall model;  StatusRequest statusRequest = StatusRequest.none;  late Cart cart;  Myservice myServices = Get.find();  int selectedColor = 0;  int quantity = 1;  String color = "";  late cartmodel cartmod;  List<cartmodel> cartitems = [];  late colormodelitems colorsmodel;  List<itemsmodelall> colorItems = [];  List indexcolor = [""];  int countcolor = 0;  @override  void onInit() {    model = Get.arguments as itemsmodelall;    cart = Cart(crud());    cartmod = cartmodel();    colorsmodel = colormodelitems(); // getCartCount(model.itemsId!);    viewcoloritem(model.itemsId!);    super.onInit();  }  @override  void onClose() {    super.onClose();  }  void selectColor(int itemscolorid) {    final colorid = (colorItems.firstWhere(      (e) => e.itemscolorId == itemscolorid.toString(),    ));    countcolor = int.parse(colorid.itemscolorQuantity ?? "0");    selectedColor = itemscolorid;    update();  }  Future<dynamic> increaseQuantity(String Item, String color) async {    statusRequest = StatusRequest.loading;    update();    var response = await cart.insertcartf(      myServices.sharedPreferences.getString("id")!,      Item,      color,    );    print(response);    print(response);    if (response['status'] == "success") {      statusRequest = StatusRequest.success;      Get.snackbar(        "Cart",        "تمت الاضافة ف سلة المنتجات",        snackPosition: SnackPosition.BOTTOM,        backgroundColor: AppColors.backgroundGrey,        colorText: Colors.white,        margin: const EdgeInsets.all(15),        borderRadius: 12,        duration: const Duration(seconds: 3),        icon: const Icon(Icons.error_outline, color: Colors.white),      );      Get.toNamed(approute.cart);    } else {      statusRequest = StatusRequest.failure;      update();      Get.snackbar(        "Cart",        "Wrong",        snackPosition: SnackPosition.BOTTOM,        backgroundColor: AppColors.newBadge,        colorText: Colors.white,        margin: const EdgeInsets.all(15),        borderRadius: 12,        duration: const Duration(seconds: 3),        icon: const Icon(Icons.error_outline, color: Colors.white),      );    }    update();  }  Future<dynamic> decreaseQuantity(String Item) async {    if (quantity <= 1) {      return;    }    statusRequest = StatusRequest.loading;    update();    var response = await cart.deletecart(      myServices.sharedPreferences.getString("id")!,      Item,    );    print(response);    if (response['status'] == "success") {      quantity = response['data']['countitem'];      List cart = [response['data']];      cartitems.clear();      cartitems.addAll(cart.map((e) => cartmodel.fromJson(e)));      Get.snackbar(        "Cart",        "تمت الازالة من سلة المنتجات",        snackPosition: SnackPosition.BOTTOM,        backgroundColor: AppColors.backgroundGrey,        colorText: Colors.white,        margin: const EdgeInsets.all(15),        borderRadius: 12,        duration: const Duration(seconds: 3),        icon: const Icon(Icons.error_outline, color: Colors.white),      );    } else {      statusRequest = StatusRequest.success;      update();      Get.snackbar(        "Cart",        "Wrong",        snackPosition: SnackPosition.BOTTOM,        backgroundColor: AppColors.newBadge,        colorText: Colors.white,        margin: const EdgeInsets.all(15),        borderRadius: 12,        duration: const Duration(seconds: 3),        icon: const Icon(Icons.error_outline, color: Colors.white),      );    }    update();  }  void addToCart() {}  void toggleFavorite() {}  @override  Future<dynamic> viewcoloritem(String item) async {    statusRequest = StatusRequest.loading;    update();    var response = await cart.viewcoloritem(item);    if (response['status'] == "success") {      statusRequest = StatusRequest.success;      List data = response['data'];      colorItems = data.map((e) => itemsmodelall.fromJson(e)).toList();      if (colorItems.isNotEmpty) {        selectColor(int.parse(colorItems.first.itemscolorId!));      }      print("selectedColor = $selectedColor");      print("length = ${colorItems.length}");      print(colorItems.map((e) => e.itemscolorQuantity).toList());    } else {      statusRequest = StatusRequest.failure;    }    update();  }  Color viewcolor(dynamic type) {    if (type == "Baby Blue" || type == "أزرق فاتح") {      return Color(0xFFD6E9F7);    } else if (type == "Beige" || type == "بيج") {      return Color(0xFFE8D9AE);    } else if (type == "Dark Gray" || type == "رمادي غامق") {      return Color(0xFF2C2C2C);    } else if (type == 'Blush Pink' || type == "وردي فاتح") {      return Color(0xFFF4D9D7);    } else if (type == 'Lavender' || type == "بنفسجي فاتح") {      return Color(0xFFD9CBEF);    } else {      return Color(0xFF2C2C2C);    }  }}